"use client";

import { motion } from "framer-motion";
import { 
  Users, Mail, CheckCircle, Wallet, PenTool, FilePlus, 
  ClipboardList, MessageCircle, Bell, 
  Activity, ArrowRight, MoreHorizontal, ArrowUpRight, Calendar, Clock
} from "lucide-react";
import { ActivityChart } from "@/components/DashboardCharts"; // ProkerChart dihapus, kita ganti widget manual
import SpotlightCard from "@/components/SpotlightCard"; 

const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

export default function AdminDashboard() {
  
  // COLOR MAPPING
  const tagColorMap: any = {
    orange: "bg-orange-100 text-orange-700 dark:bg-orange-500/20 dark:text-orange-300",
    purple: "bg-purple-100 text-purple-700 dark:bg-purple-500/20 dark:text-purple-300",
    blue: "bg-blue-100 text-blue-700 dark:bg-blue-500/20 dark:text-blue-300",
    pink: "bg-pink-100 text-pink-700 dark:bg-pink-500/20 dark:text-pink-300",
    green: "bg-green-100 text-green-700 dark:bg-green-500/20 dark:text-green-300",
  };

  const iconColorMap: any = {
    blue: "text-blue-600 group-hover:text-blue-700",
    green: "text-green-600 group-hover:text-green-700",
    orange: "text-orange-600 group-hover:text-orange-700",
    pink: "text-pink-600 group-hover:text-pink-700",
  };

  return (
    <div className="space-y-6 font-sans pb-10">
      
      {/* HEADER PROFESSIONAL */}
      <div className="flex flex-col-reverse md:flex-row justify-between items-start md:items-center gap-6 pb-2">
         <div>
            <h1 className="text-3xl font-black font-bold mb-1 text-slate-900 dark:text-white tracking-tight">
              Dashboard Overview
            </h1>
            <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">
              Selamat datang kembali, berikut ringkasan data hari ini.
            </p>
         </div>

         <div className="flex items-center gap-4">
            <button className="w-10 h-10 rounded-lg bg-white dark:bg-white/5 border border-slate-200 dark:border-white/10 flex items-center justify-center text-slate-500 hover:text-blue-600 dark:text-slate-400 dark:hover:text-white transition-colors relative shadow-sm hover:shadow-md">
               <Bell size={20} />
               <span className="absolute top-2 right-2.5 w-2 h-2 bg-red-500 rounded-full ring-2 ring-white dark:ring-[#0f172a]" />
            </button>
            
            <div className="flex items-center gap-3 pl-1 pr-4 py-1 rounded-full bg-white dark:bg-white/5 border border-slate-200 dark:border-white/10 shadow-sm cursor-pointer hover:bg-slate-50 dark:hover:bg-white/10 transition-colors">
               <div className="w-9 h-9 rounded-full bg-gradient-to-br from-blue-600 to-indigo-600 p-[2px]">
                  <div className="w-full h-full rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center overflow-hidden">
                     <span className="text-sm">😎</span>
                  </div>
               </div>
               <div className="hidden md:block">
                  <p className="text-xs font-black font-bold text-slate-800 dark:text-white leading-none">Raka Aditya</p>
                  <p className="text-[10px] font-medium text-slate-500 dark:text-slate-400 mt-0.5">Admin Pusat</p>
               </div>
            </div>
         </div>
      </div>

      {/* === STATS GRID (RADIUS PERTAMAX: ROUNDED-XL) === */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
         
         <SpotlightCard color="blue" className="p-6 rounded-xl border border-slate-200 dark:border-white/10">
            <div className="flex justify-between items-start">
               <div className="w-10 h-10 rounded-lg bg-blue-100 dark:bg-blue-500/20 flex items-center justify-center text-blue-600 dark:text-blue-400 mb-4 shadow-sm">
                  <Users size={20} />
               </div>
               <span className="px-2 py-1 rounded-md bg-green-100 dark:bg-green-500/20 text-green-700 dark:text-green-400 text-[10px] font-black font-bold">+12%</span>
            </div>
            <h3 className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Total Siswa</h3>
            <p className="text-2xl font-black font-bold text-slate-900 dark:text-white tracking-tight">1,240</p>
            <Users size={80} className="absolute -right-4 -bottom-4 text-blue-500/5 dark:text-blue-500/10 transform -rotate-12 pointer-events-none" />
         </SpotlightCard>

         <SpotlightCard color="purple" className="p-6 rounded-xl border border-slate-200 dark:border-white/10">
            <div className="w-10 h-10 rounded-lg bg-purple-100 dark:bg-purple-500/20 flex items-center justify-center text-purple-600 dark:text-purple-400 mb-4 shadow-sm">
               <Mail size={20} />
            </div>
            <h3 className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Aspirasi Baru</h3>
            <p className="text-2xl font-black font-bold text-slate-900 dark:text-white tracking-tight">18</p>
            <Mail size={80} className="absolute -right-4 -bottom-4 text-purple-500/5 dark:text-purple-500/10 transform -rotate-12 pointer-events-none" />
         </SpotlightCard>

         <SpotlightCard color="green" className="p-6 rounded-xl border border-slate-200 dark:border-white/10">
            <div className="w-10 h-10 rounded-lg bg-green-100 dark:bg-green-500/20 flex items-center justify-center text-green-600 dark:text-green-400 mb-4 shadow-sm">
               <CheckCircle size={20} />
            </div>
            <h3 className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Proker Selesai</h3>
            <p className="text-2xl font-black font-bold text-slate-900 dark:text-white tracking-tight">85%</p>
            <CheckCircle size={80} className="absolute -right-4 -bottom-4 text-green-500/5 dark:text-green-500/10 transform -rotate-12 pointer-events-none" />
         </SpotlightCard>

         <SpotlightCard color="yellow" className="p-6 rounded-xl border border-slate-200 dark:border-white/10">
            <div className="w-10 h-10 rounded-lg bg-yellow-100 dark:bg-yellow-500/20 flex items-center justify-center text-yellow-600 dark:text-yellow-400 mb-4 shadow-sm">
               <Wallet size={20} />
            </div>
            <h3 className="text-slate-500 dark:text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Dana Kas</h3>
            <p className="text-2xl font-black font-bold text-slate-900 dark:text-white tracking-tight">{formatCurrency(12500000)}</p>
            <Wallet size={80} className="absolute -right-4 -bottom-4 text-yellow-500/5 dark:text-yellow-500/10 transform -rotate-12 pointer-events-none" />
         </SpotlightCard>

      </div>

      {/* === BENTO GRID SECTION === */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
         
         {/* ITEM 1: Activity Chart */}
         <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}
            className="lg:col-span-2 bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-xl p-6 shadow-sm"
         >
            <div className="flex items-center justify-between mb-6">
               <div>
                 <h3 className="font-black font-bold text-lg text-slate-900 dark:text-white flex items-center gap-2">
                    <Activity size={20} className="text-blue-600" /> Tren Aktivitas
                 </h3>
                 <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 font-medium">Data interaksi siswa minggu ini</p>
               </div>
               <select className="bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 text-xs font-bold rounded-lg px-3 py-2 outline-none text-slate-600 dark:text-slate-300 cursor-pointer hover:bg-slate-100 dark:hover:bg-white/10 transition-colors">
                  <option>7 Hari Terakhir</option>
                  <option>30 Hari Terakhir</option>
               </select>
            </div>
            {/* Chart Container Height adjusted */}
            <div className="h-[250px]">
                <ActivityChart />
            </div>
         </motion.div>

         {/* ITEM 2: Quick Actions (Radius sharpened) */}
         <motion.div 
           initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}
           className="bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-xl p-6 shadow-sm flex flex-col"
         >
            <div className="flex items-center justify-between mb-6">
               <div className="flex items-center gap-3">
                   <div className="p-2 bg-indigo-50 dark:bg-indigo-500/20 rounded-lg text-indigo-600 dark:text-indigo-400">
                     <PenTool size={18} />
                   </div>
                   <h3 className="font-black font-bold text-md text-slate-900 dark:text-white">Akses Cepat</h3>
               </div>
            </div>
            
            <div className="grid grid-cols-2 gap-3 flex-1">
               {[
                 { label: 'Tulis Berita', icon: PenTool, color: 'blue' },
                 { label: 'Buat Proker', icon: FilePlus, color: 'green' },
                 { label: 'Cek Laporan', icon: ClipboardList, color: 'orange' },
                 { label: 'Broadcast', icon: MessageCircle, color: 'pink' },
               ].map((item, i) => (
                  <button key={i} className="relative flex flex-col items-center justify-center gap-2 p-4 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-white/10 hover:border-blue-300 dark:hover:border-blue-500/50 hover:shadow-md transition-all group active:scale-95">
                     <item.icon size={24} className={`${iconColorMap[item.color]} transition-transform duration-300`} />
                     <span className="text-xs font-black font-bold text-slate-600 dark:text-slate-300">{item.label}</span>
                     <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <ArrowUpRight size={12} className="text-slate-400"/>
                     </div>
                  </button>
               ))}
            </div>
         </motion.div>

         {/* ITEM 3: AGENDA PENTING (NEW WIDGET) */}
         <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}
            className="bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-xl p-6 shadow-sm"
         >
            <div className="flex items-center justify-between mb-4">
               <h3 className="font-black font-bold text-slate-900 dark:text-white flex items-center gap-2">
                  <Calendar size={18} className="text-orange-500" /> Agenda Penting
               </h3>
               <button className="text-[10px] bg-slate-100 dark:bg-white/10 px-2 py-1 rounded-md text-slate-600 dark:text-slate-300 font-bold hover:bg-slate-200 transition-colors">
                  Lihat Semua
               </button>
            </div>
            
            <div className="space-y-3">
               {[
                  { title: "Rapat Inti OSIS", date: "Besok, 14:00", type: "Rapat", color: "blue" },
                  { title: "LDKS Tahap 1", date: "12 Nov 2026", type: "Event", color: "purple" },
                  { title: "Deadline Proposal", date: "Dalam 3 Hari", type: "Tugas", color: "red" },
               ].map((item, i) => (
                  <div key={i} className="flex items-center gap-3 p-3 rounded-lg border border-slate-100 dark:border-white/5 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors group cursor-pointer">
                     <div className={`flex flex-col items-center justify-center w-10 h-10 rounded-lg bg-${item.color}-50 dark:bg-${item.color}-500/10 text-${item.color}-600 dark:text-${item.color}-400 font-bold text-xs leading-none border border-${item.color}-100 dark:border-${item.color}-500/20`}>
                        <Calendar size={14} className="mb-0.5 opacity-70"/>
                     </div>
                     <div className="flex-1">
                        <h4 className="text-xs font-black font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">{item.title}</h4>
                        <p className="text-[10px] text-slate-500 font-medium flex items-center gap-1 mt-0.5">
                           <Clock size={10} /> {item.date}
                        </p>
                     </div>
                     <span className={`text-[9px] font-bold px-2 py-0.5 rounded-md bg-${item.color}-100 dark:bg-${item.color}-500/20 text-${item.color}-700 dark:text-${item.color}-300`}>
                        {item.type}
                     </span>
                  </div>
               ))}
            </div>
         </motion.div>

         {/* ITEM 4: Inbox Aspirasi (Radius sharpened) */}
         <motion.div 
           initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}
           className="lg:col-span-2 bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-xl p-6 shadow-sm"
         >
            <div className="flex items-center justify-between mb-6">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-pink-50 dark:bg-pink-500/20 rounded-lg text-pink-600 dark:text-pink-400">
                    <Mail size={18} />
                  </div>
                  <h3 className="font-black font-bold text-slate-900 dark:text-white">Inbox Aspirasi</h3>
               </div>
               <button className="p-2 hover:bg-slate-100 dark:hover:bg-white/10 rounded-lg transition-colors text-slate-400">
                  <MoreHorizontal size={18} />
               </button>
            </div>

            <div className="space-y-3">
               {[
                 { name: "Ahmad (X RPL)", msg: "WC di lantai 2 tolong diperbaiki airnya...", time: "2m lalu", tag: "Sarana", color: "orange" },
                 { name: "Siti (XI TKJ)", msg: "Request lagu buat pensi besok dong!", time: "1j lalu", tag: "Event", color: "purple" },
                 { name: "Anonim", msg: "Parkiran motor makin sempit min.", time: "3j lalu", tag: "Umum", color: "blue" },
               ].map((item, i) => (
                  <div key={i} className="group flex items-center justify-between p-3 rounded-xl bg-slate-50/50 dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-white/10 hover:border-blue-200 dark:hover:border-blue-500/30 hover:shadow-sm transition-all cursor-pointer">
                     <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 flex items-center justify-center text-xs font-black font-bold text-slate-700 dark:text-slate-300 shadow-sm">
                           {item.name.charAt(0)}
                        </div>
                        <div>
                           <h4 className="text-xs font-black font-bold text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{item.name}</h4>
                           <p className="text-[10px] text-slate-500 dark:text-slate-400 line-clamp-1 mt-0.5">{item.msg}</p>
                        </div>
                     </div>
                     <div className="text-right flex flex-col items-end">
                        <span className={`text-[9px] font-black font-bold px-2 py-0.5 rounded-md mb-1 ${tagColorMap[item.color]}`}>
                          {item.tag}
                        </span>
                        <span className="text-[9px] text-slate-400 font-medium">{item.time}</span>
                     </div>
                  </div>
               ))}
            </div>
         </motion.div>

      </div>
    </div>
  );
}